const companies=['Colafix','Fixcol','Argamazza'],suppliers=['Votorantim','Intercement'],carriers=['Itamar','Marielo'],statuses=['Agendado','Carregado','Entregue','Cancelado'];
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),opts=(values,selected='')=>values.map(v=>`<option ${v===selected?'selected':''}>${esc(v)}</option>`).join(''),day=s=>s.split('-').reverse().join('/');let loads=[];
const statusClass=s=>({Agendado:'scheduled',Carregado:'loaded',Entregue:'delivered',Cancelado:'cancelled'}[s]||'scheduled');
const mondayOf=value=>{const d=value?new Date(value+'T12:00:00'):new Date(),n=d.getDay(),delta=n===0?-6:1-n;d.setDate(d.getDate()+delta);return d.toISOString().slice(0,10)};
const addDays=(iso,n)=>{const d=new Date(iso+'T12:00:00');d.setDate(d.getDate()+n);return d.toISOString().slice(0,10)};
const weekLabel=iso=>{const end=addDays(iso,4);return `${day(iso)} a ${day(end)}`};
async function refresh(){const response=await fetch('/api/cement');if(!response.ok)throw Error('Não foi possível carregar as cargas.');loads=(await response.json()).loads;for(const kind of ['granel','ensacado']){renderList(kind);renderWeek(kind);}}
async function save(row){const response=await fetch('/api/cement',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(row)}),result=await response.json();if(!response.ok)throw Error(result.error);await refresh();return result.load;}
for(const kind of ['granel','ensacado']){const root=document.querySelector('#'+kind+'-view');root.innerHTML=`<div class="cement-tabs"><button type="button" data-tab="week" aria-pressed="true">Programação semanal</button><button type="button" data-tab="list" aria-pressed="false">Todas as cargas</button></div><section class="panel cement-week-panel" data-panel="week"><div class="cement-week-head"><div><h3>Programação semanal</h3><p>Visão da agenda de segunda a sexta, baseada na programação de cimento.</p><div class="cement-week-company-filter"><span>Empresa:</span><button type="button" data-week-company="" aria-pressed="true">Todas</button><button type="button" data-week-company="Colafix" aria-pressed="false">Colafix</button><button type="button" data-week-company="Fixcol" aria-pressed="false">Fixcol</button><button type="button" data-week-company="Argamazza" aria-pressed="false">Argamazza</button></div><div class="cement-week-nav"><button type="button" data-prev>← Semana anterior</button><button type="button" data-today>Hoje</button><button type="button" data-next>Próxima semana →</button></div></div><label>Semana de<input type="date" data-week></label></div><div class="cement-week"></div></section><div data-panel="list" hidden><section class="panel cement-form-panel"><h3>Agendar carga</h3><form data-kind="${kind}"><div class="cement-fields"><label>Data agendada<input name="scheduledDate" type="date" required></label><label>Empresa<select name="company">${opts(companies)}</select></label><label>Fornecedor<select name="supplier">${opts(suppliers)}</select></label><label>Transportador<select name="carrier">${opts(carriers)}</select></label><label>Pedido do sistema<input name="systemOrder" maxlength="120" required></label><label>Pedido / contrato fornecedor<input name="supplierOrder" maxlength="120"></label>${kind==='granel'?'<label>Quantidade do pedido<input name="orderQuantity" maxlength="120" required placeholder="Ex.: 32 t"></label><label>Descrição do cimento<input name="cementDescription" maxlength="120" required value="CP II Z 40"></label>':'<input type="hidden" name="orderQuantity" value=""><input type="hidden" name="cementDescription" value="">'}<label>Número da NF<input name="invoice" maxlength="120"></label><label>Status<select name="status" class="load-status scheduled">${opts(statuses)}</select></label><label class="cement-notes">Observações / avisos<textarea name="notes" maxlength="2000" rows="2" placeholder="Ex.: parada preventiva, feriado ou informação da fábrica"></textarea></label></div><button type="submit">Salvar agendamento</button> <button type="button" data-cancel hidden>Cancelar edição</button><p class="cement-message" role="status"></p></form></section><section class="panel cement-list-panel"><h3>Acompanhamento de cargas</h3><div class="cement-filters"><label>Empresa<select data-company><option value="">Todas</option>${opts(companies)}</select></label><label>Status<select data-status><option value="">Todos</option>${opts(statuses)}</select></label><label>Buscar pedido, NF ou transportador<input type="search" data-search></label></div><div class="cement-list"></div></section></div>`;
root.dataset.weekCompany='';root.querySelectorAll('[data-week-company]').forEach(button=>button.onclick=()=>{root.dataset.weekCompany=button.dataset.weekCompany;root.querySelectorAll('[data-week-company]').forEach(x=>x.setAttribute('aria-pressed',String(x===button)));renderWeek(kind);});const weekInput=root.querySelector('[data-week]');weekInput.value=mondayOf();weekInput.onchange=()=>{weekInput.value=mondayOf(weekInput.value);renderWeek(kind)};root.querySelector('[data-prev]').onclick=()=>{weekInput.value=addDays(mondayOf(weekInput.value),-7);renderWeek(kind)};root.querySelector('[data-next]').onclick=()=>{weekInput.value=addDays(mondayOf(weekInput.value),7);renderWeek(kind)};root.querySelector('[data-today]').onclick=()=>{weekInput.value=mondayOf();renderWeek(kind)};
root.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{root.querySelectorAll('[data-tab]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));root.querySelectorAll('[data-panel]').forEach(p=>p.hidden=p.dataset.panel!==b.dataset.tab);});
const form=root.querySelector('form'),message=root.querySelector('.cement-message');form.elements.status.disabled=true;form.elements.status.onchange=()=>form.elements.status.className='load-status '+statusClass(form.elements.status.value);root.querySelectorAll('[data-company],[data-status],[data-search]').forEach(el=>el.addEventListener('input',()=>renderList(kind)));
function reset(){form.reset();if(kind==='granel')form.elements.cementDescription.value='CP II Z 40';form.elements.status.disabled=true;form.elements.status.className='load-status scheduled';delete form.dataset.id;delete form.dataset.version;root.querySelector('[data-cancel]').hidden=true;root.querySelector('.cement-form-panel h3').textContent='Agendar carga';}
root.querySelector('[data-cancel]').onclick=()=>{reset();message.textContent='Edição cancelada.';};
form.onsubmit=async e=>{e.preventDefault();const button=form.querySelector('[type=submit]');button.disabled=true;message.textContent='Salvando…';try{const input={...Object.fromEntries(new FormData(form)),kind,status:form.elements.status.value};if(form.dataset.id){input.id=form.dataset.id;input.version=Number(form.dataset.version);}await save(input);reset();message.textContent='Carga salva. Você pode atualizar o status na lista abaixo.';}catch(e){message.textContent=e.message;}finally{button.disabled=false;}};
}
function renderWeek(kind){const root=document.querySelector('#'+kind+'-view'),input=root.querySelector('[data-week]');if(!input)return;const monday=mondayOf(input.value),days=Array.from({length:5},(_,i)=>addDays(monday,i)),names=['SEGUNDA','TERÇA','QUARTA','QUINTA','SEXTA'];root.querySelector('.cement-week-head h3').textContent='Programação semanal · '+weekLabel(monday);root.querySelector('.cement-week').innerHTML=days.map((date,i)=>{const rows=loads.filter(r=>r.kind===kind&&r.scheduledDate===date&&(!root.dataset.weekCompany||r.company===root.dataset.weekCompany)).sort((a,b)=>a.createdAt.localeCompare(b.createdAt));return `<section class="cement-day"><header><strong>${names[i]}</strong><span>${day(date)}</span><b>${rows.length} ${rows.length===1?'carga':'cargas'}</b></header><div class="cement-day-body"><button type="button" class="cement-add-day" data-add-date="${date}">+ Agendar carga</button>${rows.length?rows.map(r=>`<article class="cement-load-card company-${String(r.company||'').toLowerCase()}"><div><strong>${esc(r.company)} · ${esc(r.supplier)}</strong><span class="load-status ${statusClass(r.status)}">${esc(r.status)}</span></div><p><b>Pedido sistema:</b> ${esc(r.systemOrder)}</p><p><b>Pedido/contrato:</b> ${esc(r.supplierOrder||'—')}</p>${kind==='granel'?'<p><b>Quantidade:</b> '+esc(r.orderQuantity||'—')+'</p><p><b>Cimento:</b> '+esc(r.cementDescription||'—')+'</p>':''}<p><b>NF:</b> ${esc(r.invoice||'—')}</p><p><b>Empresa:</b> ${esc(r.company)} · <b>Transp.:</b> ${esc(r.carrier)}</p>${r.notes?`<p class="cement-card-note">${esc(r.notes)}</p>`:''}</article>`).join(''):'<p class="cement-day-empty">Sem cargas agendadas.</p>'}</div></section>`}).join('');root.querySelectorAll('[data-add-date]').forEach(button=>button.onclick=()=>{const form=root.querySelector('form');root.querySelector('[data-tab="list"]').click();form.reset();form.elements.scheduledDate.value=button.dataset.addDate;if(kind==='granel')form.elements.cementDescription.value='CP II Z 40';form.elements.status.value='Agendado';form.elements.status.disabled=true;form.elements.status.className='load-status scheduled';delete form.dataset.id;delete form.dataset.version;root.querySelector('[data-cancel]').hidden=true;root.querySelector('.cement-form-panel h3').textContent='Agendar carga · '+day(button.dataset.addDate);root.querySelector('.cement-message').textContent='';form.scrollIntoView({behavior:'smooth',block:'start'});});}
function renderList(kind){const root=document.querySelector('#'+kind+'-view'),search=root.querySelector('[data-search]');if(!search)return;const q=search.value.toLocaleLowerCase('pt-BR'),company=root.querySelector('[data-company]').value,status=root.querySelector('[data-status]').value;const rows=loads.filter(r=>r.kind===kind&&(!company||r.company===company)&&(!status||r.status===status)&&[r.systemOrder,r.supplierOrder,r.orderQuantity,r.cementDescription,r.invoice,r.carrier].join(' ').toLocaleLowerCase('pt-BR').includes(q)).sort((a,b)=>b.scheduledDate.localeCompare(a.scheduledDate)||b.createdAt.localeCompare(a.createdAt));
root.querySelector('.cement-list').innerHTML=rows.length?`<div class="table-scroll"><table><thead><tr>${['Data','Empresa','Pedido sistema','Fornecedor','Pedido/contrato',...(kind==='granel'?['Quantidade','Cimento']:[]),'Transportador','NF','Status','Ações'].map(t=>`<th>${t}</th>`).join('')}</tr></thead><tbody>${rows.map(r=>`<tr><td>${day(r.scheduledDate)}</td><td>${esc(r.company)}</td><td>${esc(r.systemOrder)}</td><td>${esc(r.supplier)}</td><td>${esc(r.supplierOrder||'—')}</td>${kind==='granel'?'<td>'+esc(r.orderQuantity||'—')+'</td><td>'+esc(r.cementDescription||'—')+'</td>':''}<td>${esc(r.carrier)}</td><td>${esc(r.invoice||'—')}</td><td><select class="load-status ${statusClass(r.status)}" data-load-status="${r.id}" aria-label="Status do pedido ${esc(r.systemOrder)}">${opts(statuses,r.status)}</select></td><td><button data-edit="${r.id}">Editar</button><details><summary>Histórico</summary><ol class="load-timeline">${r.history.filter(h=>h.changes?.status).map(h=>`<li><span class="load-status ${statusClass(h.changes.status.after)}">${esc(h.changes.status.after)}</span><time datetime="${esc(h.at)}">${esc(new Date(h.at).toLocaleString('pt-BR'))}</time></li>`).join('')}</ol></details></td></tr>`).join('')}</tbody></table></div>`:'<p class="empty-state">Nenhuma carga encontrada. Cadastre o primeiro agendamento acima.</p>';
root.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>{const r=loads.find(r=>r.id===b.dataset.edit),form=root.querySelector('form');for(const [k,v] of Object.entries(r))if(form.elements.namedItem(k))form.elements.namedItem(k).value=v;form.dataset.id=r.id;form.dataset.version=r.version;form.elements.status.disabled=false;form.elements.status.className='load-status '+statusClass(r.status);root.querySelector('[data-cancel]').hidden=false;root.querySelector('.cement-form-panel h3').textContent='Editar carga · pedido '+r.systemOrder;root.querySelector('.cement-message').textContent='';root.querySelector('[data-tab="list"]').click();form.scrollIntoView({behavior:'smooth'});});
root.querySelectorAll('[data-load-status]').forEach(select=>select.onchange=async()=>{const r=loads.find(r=>r.id===select.dataset.loadStatus),message=root.querySelector('.cement-message');select.disabled=true;try{await save({...r,status:select.value});message.textContent='Status atualizado e registrado no histórico.';}catch(e){select.value=r.status;select.disabled=false;message.textContent=e.message;}});
}
refresh().catch(e=>document.querySelectorAll('.cement-message').forEach(p=>p.textContent=e.message));